INSERT INTO `policies` VALUES ('1f58b81775f74362bf88a388fc792308', '关于支持乡村振兴重点帮扶县的实施意见', '金融支持', '全国', '国家乡村振兴局', '为支持乡村振兴重点帮扶县发展，提出一系列金融支持政策，包括贷款贴息、风险补偿等。', '<h3>政策内容\n            </h3><p>为深入贯彻落实党中央、国务院关于巩固拓展脱贫攻坚成果同乡村振兴有效衔接的决策部署，进一步支持乡村振兴重点帮扶县发展，提出如下实施意见：\n            </p><h4>一、总体要求</h4><p>以习近平新时代中国特色社会主义思想为指导，坚持农业农村优先发展，加大对乡村振兴重点帮扶县的金融支持力度，建立健全多元化、广覆盖、可持续的农村金融服务体系。</p><p><br></p><h4>二、主要措施</h4><ol><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>加大信贷支持力度</strong>：对符合条件的农业经营主体给予贷款贴息，利率不超过同期LPR的50%。</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>设立风险补偿基金</strong>：中央财政安排专项资金50亿元，用于建立乡村振兴贷款风险补偿机制。</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>创新金融产品</strong>：开发适合农村特点的保险产品，包括特色农产品保险、价格指数保险等。</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>支持基础设施建设</strong>：提供期限15年、利率3.85%的长期低息贷款支持农村道路、水利等基础设施建设。</li></ol><p>\n\n            </p><h4>三、申请条件</h4><p><br></p><p>申请本政策支持的县需满足以下条件：\n            </p><h4>四、申请流程</h4><p>\n            </p><ol><li><span class=\"ql-ui\" contenteditable=\"false\"></span>县级人民政府向省级乡村振兴部门提交申请材料；</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span>省级部门组织专家评审，审核通过后报送国家乡村振兴局；</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span>国家乡村振兴局会同财政部、农业农村部进行联合审批；</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span>审批通过后15个工作日内下达资金。</li></ol><p>\n\n            </p><h4>五、监督管理</h4><p>\n            </p><p>建立动态监测评估机制，每季度上报资金使用情况，每年开展绩效评价，对违规使用资金的地区将收回补助并取消下一年度申报资格。</p><p>\n</p><h4>六、截止日期</h4><p>\n</p><p>本政策执行至2025年12月31日。</p>', '国家乡村振兴局规划财务司', '张处长', '010-84419999', '北京市朝阳区农展馆南里11号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('294c9c66a52241759e75030014201b4e', '浙江省农业产业化重点龙头企业扶持办法', '补贴政策', '浙江省', '浙江省农业农村厅', '对省级农业产业化重点龙头企业给予资金补贴、税收优惠等政策支持。', '<h3>第一章 总则</h3>\n            <p>为培育壮大农业产业化重点龙头企业，带动农民增收，促进乡村产业振兴，制定本办法。</p>\n\n            <h3>第二章 认定条件</h3>\n            <p>申报企业需同时满足以下条件：</p>\n            <ol>\n                <li>在浙江省内注册，具有独立法人资格，经营3年以上；</li>\n                <li>年销售收入：种植业5000万元以上，畜牧业8000万元以上，渔业6000万元以上；</li>\n                <li>带动农户1000户以上，签订稳定的购销合同；</li>\n                <li>资产负债率低于60%，银行信用等级AA级以上；</li>\n                <li>有自主品牌和稳定的销售渠道。</li>\n            </ol>\n\n            <h3>第三章 扶持政策</h3>\n            <ul>\n                <li><strong>资金奖励</strong>：新认定的省级龙头企业一次性奖励50万元；</li>\n                <li><strong>税收优惠</strong>：享受企业所得税减免政策，减按15%的税率征收；</li>\n                <li><strong>用地支持</strong>：优先安排农业设施用地，用地指标单列；</li>\n                <li><strong>项目扶持</strong>：在申报省级以上农业项目时优先支持；</li>\n                <li><strong>金融支持</strong>：享受\"浙里贷\"专属信贷产品，利率优惠30%。</li>\n            </ul>\n\n            <h3>第四章 申报程序</h3>\n            <ol>\n                <li>企业向所在地县级农业农村部门申报；</li>\n                <li>县级初审后报市级农业农村部门；</li>\n                <li>市级审核后报省农业农村厅；</li>\n                <li>省农业农村厅组织专家评审并公示；</li>\n                <li>公示无异议后发文认定。</li>\n            </ol>\n\n            <h3>第五章 监督管理</h3>\n            <p>实行年度考核制度，对考核不合格的企业取消资格并追回奖励资金。认定有效期为3年，期满后需重新申报。</p>\n\n            <h3>第六章 附则</h3>\n            <p>本办法自发布之日起施行，由浙江省农业农村厅负责解释。</p>', '浙江省农业农村厅产业化处', '王科长', '0571-86757777', '杭州市凤起东路29号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('507850c118d74d4f8688824792af12b8', '云南省消费帮扶助力乡村振兴实施方案', '营销帮扶', '云南省', '云南省乡村振兴局', '动员社会各界参与消费帮扶，拓宽脱贫地区农产品销售渠道。', '<h3>一、工作目标</h3>\n            <p>到2025年，实现消费帮扶金额年均增长15%以上，累计帮助销售脱贫地区农产品500亿元以上，打造100个消费帮扶示范企业。</p>\n\n            <h3>二、重点任务</h3>\n            <ol>\n                <li><strong>政府采购</strong>：各级预算单位按照不低于年度农副产品采购总额的30%采购脱贫地区产品；</li>\n                <li><strong>东西协作</strong>：深化沪滇、粤滇协作，建立稳定的产销对接机制；</li>\n                <li><strong>社会参与</strong>：动员民营企业、社会组织等参与消费帮扶；</li>\n                <li><strong>平台建设</strong>：打造\"云品出滇\"电商平台，建设1000个消费帮扶专柜。</li>\n            </ol>\n\n            <h3>三、支持政策</h3>\n            <ul>\n                <li>对年采购脱贫地区农产品500万元以上的企业，给予采购额3%的奖励；</li>\n                <li>消费帮扶示范企业可享受\"绿色通道\"政策，减免相关税费；</li>\n                <li>支持脱贫地区农产品品牌建设，给予品牌宣传费用50%的补贴；</li>\n                <li>对参与消费帮扶的物流企业，给予每单0.3元的运费补贴。</li>\n            </ul>\n\n            <h3>四、保障措施</h3>\n            <ol>\n                <li>建立消费帮扶产品目录，实行动态管理；</li>\n                <li>加强产品质量监管，建立溯源体系；</li>\n                <li>开展消费帮扶月活动，组织产销对接会；</li>\n                <li>将消费帮扶纳入乡村振兴考核内容。</li>\n            </ol>\n\n            <h3>五、申报方式</h3>\n            <p>符合条件的企业可登录云南省消费帮扶公共服务平台在线申报，或向当地乡村振兴部门提交纸质材料。</p>', '云南省乡村振兴局社会扶贫处', '赵科长', '0871-65712888', '昆明市盘龙区万华路169号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('629834e80d9a4667ae68ba1b806eba82', '贵州省乡村振兴致富带头人培训计划', '教育培训', '贵州省', '贵州省乡村振兴局', '组织乡村致富带头人参加培训，提升经营管理能力，带动乡村产业发展。', '<h3>一、培训目标</h3>\n            <p>到2025年，为全省66个脱贫县培养1万名乡村振兴致富带头人，每人带动10户以上农户增收，形成\"头雁\"引领、\"雁阵\"齐飞的乡村人才发展格局。</p>\n\n            <h3>二、培训对象</h3>\n            <ul>\n                <li>村\"两委\"成员、驻村第一书记；</li>\n                <li>农民合作社负责人、家庭农场主；</li>\n                <li>返乡创业人员、退役军人；</li>\n                <li>农村电商、乡村旅游等新业态经营者。</li>\n            </ul>\n\n            <h3>三、培训内容</h3>\n            <ol>\n                <li><strong>政策解读</strong>：乡村振兴战略、农业农村政策；</li>\n                <li><strong>实用技术</strong>：特色种植、生态养殖、农产品加工；</li>\n                <li><strong>经营管理</strong>：合作社运营、品牌建设、财务管理；</li>\n                <li><strong>市场营销</strong>：电商运营、直播带货、渠道拓展；</li>\n                <li><strong>案例教学</strong>：实地考察成功案例，学习先进经验。</li>\n            </ol>\n\n            <h3>四、培训方式</h3>\n            <ul>\n                <li><strong>集中培训</strong>：每年组织2期，每期15天，在贵州大学等高校举办；</li>\n                <li><strong>线上学习</strong>：通过\"黔农云\"平台提供全年在线课程；</li>\n                <li><strong>实地指导</strong>：安排专家团队定期下乡指导；</li>\n                <li><strong>跟踪服务</strong>：建立学员档案，提供3年跟踪服务。</li>\n            </ul>\n\n            <h3>五、政策支持</h3>\n            <ol>\n                <li>培训费用全免，并给予每人每天100元生活补助；</li>\n                <li>优秀学员可获得最高10万元创业担保贷款；</li>\n                <li>带动效果显著的，授予\"乡村振兴带头人\"称号并给予5万元奖励。</li>\n            </ol>\n\n            <h3>六、报名方式</h3>\n            <p>有意向者可通过以下方式报名：</p>\n            <ul>\n                <li>向所在村委会提出申请，由乡镇统一推荐；</li>\n                <li>登录贵州省乡村振兴局官网在线报名；</li>\n                <li>拨打服务热线0851-86890000咨询。</li>\n            </ul>', '贵州省乡村振兴局培训中心', '刘老师', '0851-86890000', '贵阳市云岩区中华北路242号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('659fbf22a2b347309a83dc4550a92da9', '四川省乡村振兴金融创新试点方案', '金融支持', '四川省', '四川省地方金融监管局', '在乡村振兴重点帮扶县开展金融产品和服务创新试点。', '<h3>一、试点范围</h3>\n            <p>在全省25个国家乡村振兴重点帮扶县开展试点，期限3年。</p>\n\n            <h3>二、试点内容</h3>\n            <ol>\n                <li><strong>信贷产品创新</strong>：开发\"乡村振兴贷\"\"特色产业贷\"等专属产品；</li>\n                <li><strong>抵押担保创新</strong>：开展农村承包土地经营权、集体资产股权等抵押贷款；</li>\n                <li><strong>服务模式创新</strong>：建立\"金融村官\"制度，开展整村授信；</li>\n                <li><strong>风险分担创新</strong>：建立政府、银行、保险多方参与的风险分担机制。</li>\n            </ol>\n\n            <h3>三、支持政策</h3>\n            <ul>\n                <li>人民银行成都分行安排100亿元再贷款额度支持试点；</li>\n                <li>省财政设立5亿元风险补偿基金；</li>\n                <li>试点县不良贷款容忍度提高2个百分点；</li>\n                <li>对试点成效显著的金融机构给予奖励。</li>\n            </ul>\n\n            <h3>四、保障措施</h3>\n            <ol>\n                <li>建立省级部门联席会议制度；</li>\n                <li>开展金融知识下乡活动；</li>\n                <li>完善农村信用体系建设；</li>\n                <li>加强试点效果评估。</li>\n            </ol>\n\n            <h3>五、申报方式</h3>\n            <p>有意向的县（市、区）可向省地方金融监管局提交试点申请，经评审后确定试点名单。</p>', '四川省地方金融监管局农村金融处', '杨处长', '028-86605555', '成都市高新区天府大道北段966号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('6f6d3076c99b43cf8082255fd40f3073', '农产品电商营销扶持政策', '营销帮扶', '全国', '商务部', '支持农产品电商发展，提供平台入驻优惠、流量支持和物流补贴等政策。', '<h3>一、支持对象</h3>\n            <p>在县域内注册的农产品电商企业、合作社、家庭农场等经营主体，需满足以下条件：</p>\n            <ul>\n                <li>年农产品网络销售额达到50万元以上；</li>\n                <li>带动农户20户以上增收；</li>\n                <li>有固定的生产经营场所和电商运营团队。</li>\n            </ul>\n\n            <h3>二、支持内容</h3>\n            <ol>\n                <li><strong>平台入驻优惠</strong>：与主流电商平台合作，提供首年平台服务费减免50%的政策。</li>\n                <li><strong>流量扶持</strong>：每年组织2次\"农产品电商节\"，给予参与企业专属流量支持。</li>\n                <li><strong>物流补贴</strong>：对农产品上行快递费用，按照实际发生额的30%给予补贴，每家企业每年最高5万元。</li>\n                <li><strong>品牌建设</strong>：支持农产品品牌打造和包装设计，给予50%的费用补贴。</li>\n            </ol>\n\n            <h3>三、申报材料</h3>\n            <ul>\n                <li>企业营业执照复印件；</li>\n                <li>农产品电商销售证明（平台后台数据截图）；</li>\n                <li>带动农户增收证明（村委会盖章）；</li>\n                <li>项目实施方案和资金使用计划。</li>\n            </ul>\n\n            <h3>四、申报流程</h3>\n            <ol>\n                <li>企业向县级商务部门提交申请材料；</li>\n                <li>县级商务部门初审后报省级商务部门；</li>\n                <li>省级商务部门组织专家评审；</li>\n                <li>公示无异议后下达补助资金。</li>\n            </ol>\n\n            <h3>五、监督管理</h3>\n            <p>获得支持的企业需每季度报送经营情况，对弄虚作假的企业将追回补助资金并列入黑名单。</p>\n\n            <h3>六、政策期限</h3>\n            <p>本政策执行至2024年12月31日。</p>', '商务部电子商务司', '赵处长', '010-65197456', '北京市东城区东长安街2号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('b36832ad8d4240b19ae27f0f71ab2976', '农业科技特派员助力乡村振兴行动计划', '技术支持', '全国', '农业农村部', '组织农业科技人员下乡服务，为农民提供技术指导和培训，提升农业生产技术水平。', '<h3>一、目标任务</h3>\n            <p>到2025年，实现全国832个脱贫县科技特派员全覆盖，每年组织10万名农业科技人员下乡服务，建设1万个科技特派员工作站，培训农村实用人才100万人次。</p>\n\n            <h3>二、选派条件</h3>\n            <ul>\n                <li>具有中级以上专业技术职称或硕士以上学历；</li>\n                <li>从事农业科研、教学或技术推广工作3年以上；</li>\n                <li>熟悉农业农村情况，有实际工作经验；</li>\n                <li>每年下乡服务时间不少于90天。</li>\n            </ul>\n\n            <h3>三、工作内容</h3>\n            <ol>\n                <li><strong>技术指导</strong>：解决农业生产中的技术难题，推广新品种、新技术、新模式。</li>\n                <li><strong>产业规划</strong>：帮助制定乡村产业发展规划，培育特色优势产业。</li>\n                <li><strong>人才培养</strong>：开展实用技术培训，培养农村致富带头人。</li>\n                <li><strong>成果转化</strong>：促进农业科技成果转化应用，提高农业生产效益。</li>\n            </ol>\n\n            <h3>四、保障措施</h3>\n            <ul>\n                <li>中央财政按照每人每年3万元标准给予工作经费补助；</li>\n                <li>服务期满考核优秀的，在职称评定、岗位晋升中优先考虑；</li>\n                <li>鼓励科技特派员以技术入股、成果转让等方式参与利益分配；</li>\n                <li>为科技特派员购买人身意外伤害保险。</li>\n            </ul>\n\n            <h3>五、申报程序</h3>\n            <ol>\n                <li>县级农业农村部门提出需求申请；</li>\n                <li>省级农业农村部门统筹安排选派计划；</li>\n                <li>科研院所、高校组织人员报名；</li>\n                <li>签订三方服务协议，明确责任义务。</li>\n            </ol>\n\n            <h3>六、联系方式</h3>\n            <p>本计划长期有效，有意向的单位和个人可随时申报。</p>', '农业农村部科技教育司', '李科长', '010-59193000', '北京市朝阳区农展馆南里11号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('bcae27d563fa4bdf80265703ef771929', '广东省现代农业产业园建设扶持政策', '补贴政策', '广东省', '广东省农业农村厅', '支持现代农业产业园建设，对省级产业园给予财政资金支持。', '<h3>一、建设目标</h3>\n            <p>到2025年，建设200个省级现代农业产业园，实现农业县全覆盖，产业园内农民收入高于当地平均水平15%以上。</p>\n\n            <h3>二、支持方向</h3>\n            <ol>\n                <li>优势特色产业引领区；</li>\n                <li>现代技术与装备集成区；</li>\n                <li>一二三产业融合发展区；</li>\n                <li>新型经营主体创业创新孵化区；</li>\n                <li>农业高质量发展示范区。</li>\n            </ol>\n\n            <h3>三、支持政策</h3>\n            <ul>\n                <li>每个省级产业园省级财政补助5000万元；</li>\n                <li>市县财政按不低于1:1比例配套；</li>\n                <li>产业园建设用地指标单列；</li>\n                <li>产业园企业享受税收减免政策；</li>\n                <li>优先支持产业园主体申报农业项目。</li>\n            </ul>\n\n            <h3>四、申报条件</h3>\n            <p>申报产业园需满足以下条件：</p>\n            <ol>\n                <li>主导产业产值占产业园总产值50%以上；</li>\n                <li>规划面积5万亩以上，核心区3000亩以上；</li>\n                <li>有3家以上农业龙头企业带动；</li>\n                <li>有明确的建设规划和实施方案。</li>\n            </ol>\n\n            <h3>五、考核验收</h3>\n            <p>实行\"目标考核、动态管理、能进能出\"的管理机制，对考核不合格的产业园取消资格并追回资金。</p>', '广东省农业农村厅产业园办公室', '陈科长', '020-37288888', '广州市天河区先烈东路135号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('d89db230c4fe45bcb766a34724994847', '甘肃省特色农产品保险补贴实施方案', '金融支持', '甘肃省', '甘肃省农业农村厅', '对苹果、中药材等特色农产品保险给予保费补贴，降低农民生产风险。', '<h3>一、补贴品种</h3>\n            <p>首批纳入补贴范围的特色农产品包括：</p>\n            <ul>\n                <li>苹果（覆盖天水、平凉、庆阳等主产区）；</li>\n                <li>中药材（当归、黄芪、党参等道地品种）；</li>\n                <li>高原夏菜（兰州、张掖、武威等产区）；</li>\n                <li>小杂粮（荞麦、藜麦、谷子等）。</li>\n            </ul>\n\n            <h3>二、保险责任</h3>\n            <p>保险责任包括但不限于以下风险：</p>\n            <ol>\n                <li>自然灾害：干旱、洪涝、冰雹、霜冻等；</li>\n                <li>病虫害：经农业部门认定的重大病虫害；</li>\n                <li>价格波动：市场价格低于保险合同约定价格。</li>\n            </ol>\n\n            <h3>三、补贴标准</h3>\n            <table border=\"1\" cellpadding=\"5\" cellspacing=\"0\">\n                <tr>\n                    <th>品种</th>\n                    <th>保险费率</th>\n                    <th>省级补贴</th>\n                    <th>市县补贴</th>\n                    <th>农户自缴</th>\n                </tr>\n                <tr>\n                    <td>苹果</td>\n                    <td>5%</td>\n                    <td>50%</td>\n                    <td>30%</td>\n                    <td>20%</td>\n                </tr>\n                <tr>\n                    <td>中药材</td>\n                    <td>6%</td>\n                    <td>60%</td>\n                    <td>20%</td>\n                    <td>20%</td>\n                </tr>\n                <tr>\n                    <td>高原夏菜</td>\n                    <td>4.5%</td>\n                    <td>50%</td>\n                    <td>30%</td>\n                    <td>20%</td>\n                </tr>\n                <tr>\n                    <td>小杂粮</td>\n                    <td>3.5%</td>\n                    <td>70%</td>\n                    <td>20%</td>\n                    <td>10%</td>\n                </tr>\n            </table>\n\n            <h3>四、理赔流程</h3>\n            <ol>\n                <li>农户在灾害发生后24小时内向保险公司报案；</li>\n                <li>保险公司会同农业部门现场查勘定损；</li>\n                <li>公示定损结果无异议后，10个工作日内支付赔款。</li>\n            </ol>\n\n            <h3>五、实施期限</h3>\n            <p>本方案自2023年1月1日起实施，有效期3年。</p>', '甘肃省农业农村厅计划财务处', '马科长', '0931-8179111', '兰州市城关区平凉路106号', '2025-08-23 00:40:52');
INSERT INTO `policies` VALUES ('e3e0109cfef740a4903ff88496a634e1', '黑龙江省黑土地保护利用补贴政策', '补贴政策', '黑龙江省', '黑龙江省农业农村厅', '对采取黑土地保护措施的农户和新型经营主体给予补贴。', '<h3>一、补贴对象</h3>\n            <p>在黑龙江省黑土区范围内，采取以下保护措施的农户和新型农业经营主体：</p>\n            <ul>\n                <li>实施秸秆还田的；</li>\n                <li>开展轮作休耕的；</li>\n                <li>使用有机肥替代化肥的；</li>\n                <li>建设农田防护林的。</li>\n            </ul>\n\n            <h3>二、补贴标准</h3>\n            <ol>\n                <li>秸秆还田：每亩补贴40元；</li>\n                <li>轮作休耕：每亩补贴150元；</li>\n                <li>有机肥替代：每亩补贴100元；</li>\n                <li>农田防护林：每亩补贴500元。</li>\n            </ol>\n\n            <h3>三、申报条件</h3>\n            <p>申报主体需满足以下条件：</p>\n            <ul>\n                <li>在黑土区范围内合法经营耕地；</li>\n                <li>耕地面积不低于50亩；</li>\n                <li>按要求采取保护措施并达到技术标准；</li>\n                <li>承诺连续实施3年以上。</li>\n            </ul>\n\n            <h3>四、监督管理</h3>\n            <p>建立黑土地保护利用台账，采取卫星遥感监测和实地核查相结合的方式，对弄虚作假的取消补贴资格并追回资金。</p>\n\n            <h3>五、政策期限</h3>\n            <p>本政策自2023年1月1日起实施，有效期5年。</p>', '黑龙江省农业农村厅耕地保护处', '孙科长', '0451-82310555', '哈尔滨市香坊区文府街4-1号', '2025-08-23 00:40:52');
INSERT INTO `products` VALUES ('0c212c1dea134749ac07fc20ae097fb6', '云南冰糖橙', '冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高', 39.90, '/profile/upload/2025/08/20/1.云南冰糖橙_20250820173435A001.png', '云南新平', '云南玉溪', 996.00, '5斤家庭装', '常温10天，冷藏20天', '阴凉干燥', '即食', '<h2><strong>产品详情</strong></h2><p>冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高。</p><p><br></p><h2><strong>种植环境</strong></h2><p>哀牢山梯田种植，精准水肥管理。</p><p><br></p><h2><strong>品质保证</strong></h2><p>糖度检测，单果≥13度。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('120d6b68e06f43958801a5656736dcf7', '新疆库尔勒香梨', '皮薄肉细，汁多味甜，酥脆爽口', 15.90, '/profile/upload/2025/08/20/2.新疆库尔勒香梨_20250820173440A002.png', '新疆库尔勒', '新疆库尔勒', 996.00, '3斤装', '常温10天，冷藏20天', '阴凉通风处存放', '即食', '<h2><strong>产品详情</strong></h2><p>新疆库尔勒香梨，皮薄肉细，汁多味甜，酥脆爽口，被誉为\'梨中珍品\'。</p><p><br></p><h2><strong>种植环境</strong></h2><p>生长在塔里木盆地北缘，充足的日照和天山雪水灌溉造就了独特风味。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工精选，大小均匀，坏果包赔。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('20c59e8a5614416eb07917f7201dcd73', '高原有机苹果', '甘肃张掖高海拔种植，自然成熟，香甜脆爽', 12.80, '/profile/upload/2025/08/20/3.高原有机苹果_20250820173445A003.png', '甘肃张掖', '甘肃张掖', 1000.00, '5斤装', '常温15天，冷藏30天', '阴凉干燥处存放或冷藏', '即食', '<h2><strong>产品详情</strong></h2><p>我们的高原有机苹果生长在甘肃张掖海拔1500米以上的高原地区，昼夜温差大，光照充足，使得苹果糖分积累充足，口感脆甜。</p><p><br></p><h2><strong>种植环境</strong></h2><p>果园位于祁连山脚下，空气清新，水源纯净，采用有机种植方式，不使用化学农药和化肥，完全依靠有机肥料和生物防治。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每一颗苹果都经过严格筛选，确保大小均匀，色泽鲜艳，无瑕疵。我们承诺如收到坏果，将按比例赔偿。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('2aa126b04ddc403da657f64061c7a8a1', '莱阳沙地梨', '莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺', 28.80, '/profile/upload/2025/08/20/4.莱阳沙地梨_20250820173450A004.png', '山东莱阳', '山东烟台', 1000.00, '5斤精品装', '常温7天，冷藏15天', '阴凉通风', '即食', '<h2><strong>产品详情</strong></h2><p>莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺。</p><p><br></p><h2><strong>种植环境</strong></h2><p>五龙河冲积沙土种植，富含矿物质。</p><p><br></p><h2><strong>品质保证</strong></h2><p>现摘现发，坏果包赔。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('2c1af27393734311b1d7f84fda73f7a9', '四川爱媛38号橙', '果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美', 22.50, '/profile/upload/2025/08/20/5.四川爱媛38号橙_20250820173456A005.png', '四川丹棱', '四川眉山', 1000.00, '5斤精品装', '常温7天，冷藏15天', '阴凉通风', '即食', '<h2><strong>产品详情</strong></h2><p>果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美。</p><p><br></p><h2><strong>种植环境</strong></h2><p>四川盆地丘陵地带，全年超2000小时日照。</p><p><br></p><h2><strong>品质保证</strong></h2><p>单果套袋，坏果按个赔付。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('2c1e980af1f14700ae63e2661e246f03', '阳澄湖大闸蟹', '正宗阳澄湖产区，蟹黄饱满，蟹肉鲜甜，青背白肚金爪', 198.00, '/profile/upload/2025/08/20/6.阳澄湖大闸蟹_20250820173501A006.png', '江苏苏州', '江苏昆山', 1000.00, '4只装（3两/只）', '鲜活运输，收货后冷藏3天', '冷藏保湿', '需蒸煮', '<h2><strong>产品详情</strong></h2><p>正宗阳澄湖产区，蟹黄饱满，蟹肉鲜甜，青背白肚金爪。</p><p><br></p><h2><strong>养殖环境</strong></h2><p>湖心水域围网养殖，投喂小鱼螺蛳。</p><p><br></p><h2><strong>品质保证</strong></h2><p>佩戴防伪戒指，死蟹包赔。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('37bdaacbd96446a1baef0d424d1c16da', '五常稻花香大米', '五常核心产区稻花香大米，米粒细长，油润饱满，饭香浓郁', 89.90, '/profile/upload/2025/08/20/7.五常稻花香大米_20250820173512A008.png', '黑龙江五常', '黑龙江哈尔滨', 1000.00, '5kg装', '阴凉干燥处12个月', '避光防潮', '需烹饪', '<h2><strong>产品详情</strong></h2><p>五常核心产区稻花香大米，米粒细长，油润饱满，蒸煮后饭香浓郁。</p><p><br></p><h2><strong>种植环境</strong></h2><p>黑土地种植，松花江水源灌溉，一年一季慢生长。</p><p><br></p><h2><strong>品质保证</strong></h2><p>当季新米，真空包装，假一赔十。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('3ac3b3ac46d84eff81c80244f259ede9', '茂名妃子笑荔枝', '妃子笑荔枝，果大核小，肉厚多汁，酸甜比例恰到好处', 36.80, '/profile/upload/2025/08/20/8.茂名妃子笑荔枝_20250820173508A007.png', '广东茂名', '广东茂名', 1000.00, '3斤礼盒装', '冷藏3-5天', '冷藏保存', '即食', '<h2><strong>产品详情</strong></h2><p>妃子笑荔枝，果大核小，肉厚多汁，酸甜比例恰到好处。</p><p><br></p><h2><strong>种植环境</strong></h2><p>茂名高州核心产区，火山岩土壤种植，日照充足。</p><p><br></p><h2><strong>品质保证</strong></h2><p>清晨采摘，冷链运输，坏果包赔。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('4127bee163d740ddb97d9e31af8f90c1', '盱眙清水小龙虾', '清水养殖小龙虾，壳薄肉厚，腮白腹净，肉质Q弹', 88.00, '/profile/upload/2025/08/20/9.盱眙清水小龙虾_20250820173728A009.png', '江苏盱眙', '江苏淮安', 1000.00, '1.5kg（4-6钱/只）', '冷冻6个月', '-18℃冷冻', '需烹饪', '<h2><strong>产品详情</strong></h2><p>清水养殖小龙虾，壳薄肉厚，腮白腹净，肉质Q弹。</p><p><br></p><h2><strong>养殖环境</strong></h2><p>洪泽湖活水养殖，科学投喂。</p><p><br></p><h2><strong>品质保证</strong></h2><p>超声波清洗，-40℃速冻保鲜。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('46d60aecaf2b4d5a95449257f31a5a17', '福建琯溪蜜柚', '果大皮薄，瓤肉无籽，汁多柔软，清甜微酸', 39.90, '/profile/upload/2025/08/20/10.福建琯溪蜜柚_20250820173732A010.png', '福建平和', '福建平和', 1000.00, '1个装(约2.5kg)', '常温30天', '阴凉通风处存放', '即食', '<h2><strong>产品详情</strong></h2><p>福建琯溪蜜柚，果大皮薄，瓤肉无籽，汁多柔软，清甜微酸。</p><p><br></p><h2><strong>种植环境</strong></h2><p>福建平和县独特气候条件，采用有机种植。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每个蜜柚独立包装，坏果包赔。</p>', 100, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('48dc3322c10d48dd8fa76a014e0d172b', '海南贵妃芒果', '果肉金黄，纤维极少，甜度高达18度以上', 29.90, '/profile/upload/2025/08/20/11.海南贵妃芒果_20250820173738A011.png', '海南三亚', '海南三亚', 1000.00, '4个装', '常温5天，冷藏10天', '常温催熟后冷藏', '需催熟', '<h2><strong>产品详情</strong></h2><p>海南贵妃芒果，果肉金黄，纤维极少，甜度高达18度以上。</p><p><br></p><h2><strong>种植环境</strong></h2><p>海南三亚热带气候，充足日照，自然成熟。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每个芒果独立包装，坏果包赔。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('63d77b62432f4444847ba0bf39dd79d3', '云南普洱熟茶饼', '勐海茶区发酵熟普，陈香醇厚，汤色红亮，回甘持久', 128.00, '/profile/upload/2025/08/20/12.云南普洱熟茶饼_20250820173743A012.png', '云南勐海', '云南西双版纳', 1000.00, '357g/饼', '长期保存', '通风避光', '需冲泡', '<h2><strong>产品详情</strong></h2><p>勐海茶区发酵熟普，陈香醇厚，汤色红亮，回甘持久。</p><p><br></p><h2><strong>仓储环境</strong></h2><p>干仓存放5年，温湿度严格把控。</p><p><br></p><h2><strong>品质保证</strong></h2><p>茶饼压制紧实，金芽显露。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('6e51651e7d044ce3b1b732afcdeb9461', '临安手剥山核桃', '临安手剥山核桃，颗粒饱满，香脆可口，淡淡奶香味', 58.00, '/profile/upload/2025/08/20/13.临安手剥山核桃_20250820173748A013.png', '浙江临安', '浙江杭州', 1000.00, '250g罐装', '密封6个月', '密封防潮', '即食', '<h2><strong>产品详情</strong></h2><p>临安手剥山核桃，颗粒饱满，香脆可口，淡淡奶香味。</p><p><br></p><h2><strong>种植环境</strong></h2><p>天目山脉海拔500米以上，自然落果采收。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工筛选，坏籽率＜2%。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('6f06ce25f9d74832b1136ba79630d5e0', '锡林郭勒羔羊肉', '草原放养羔羊，肉质细嫩，膻味轻，富含不饱和脂肪酸', 138.00, '/profile/upload/2025/08/20/14.锡林郭勒羔羊肉_20250820173753A014.png', '内蒙古锡林郭勒', '内蒙古锡林浩特', 1000.00, '2kg套餐（4部位）', '冷冻12个月', '-18℃冷冻', '需烹饪', '<h2><strong>产品详情</strong></h2><p>草原放养羔羊，肉质细嫩，膻味轻，富含不饱和脂肪酸。</p><p><br></p><h2><strong>养殖环境</strong></h2><p>锡林郭勒草原自然放牧，食百草饮泉水。</p><p><br></p><h2><strong>品质保证</strong></h2><p>排酸处理，-38℃急冻锁鲜。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('92a6d75159254cf9b1d962114ae91e4a', '武夷山金骏眉', '桐木关金骏眉，金毫显露，蜜香浓郁，回甘持久', 268.00, '/profile/upload/2025/08/20/15.武夷山金骏眉_20250820173758A015.png', '福建武夷山', '福建南平', 1000.00, '50g礼盒装', '密封24个月', '避光密封', '需冲泡', '<h2><strong>产品详情</strong></h2><p>桐木关金骏眉，金毫显露，蜜香浓郁，回甘持久。</p><p><br></p><h2><strong>种植环境</strong></h2><p>武夷山国家级自然保护区，海拔1200米以上。</p><p><br></p><h2><strong>品质保证</strong></h2><p>传统工艺制作，茶芽完整。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('94f1070c8767441bb5453686e34775c3', '宁夏头茬枸杞', '头茬枸杞，自然晾晒，颗粒饱满，色泽暗红，甘甜无涩味', 45.00, '/profile/upload/2025/08/20/16.宁夏头茬枸杞_20250820173803A016.png', '宁夏中宁', '宁夏中卫', 1000.00, '250g罐装', '密封18个月', '密封防潮', '即食/泡茶', '<h2><strong>产品详情</strong></h2><p>头茬枸杞，自然晾晒，颗粒饱满，色泽暗红，甘甜无涩味。</p><p><br></p><h2><strong>种植环境</strong></h2><p>黄河水灌溉，昼夜温差大，富硒土壤种植。</p><p><br></p><h2><strong>品质保证</strong></h2><p>无硫熏染，杂质率＜1%。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('bc0e739b061a48829a1da11c7e90b2fb', '山东红富士苹果', '果形端正，色泽鲜艳，肉质细脆，酸甜适口', 9.90, '/profile/upload/2025/08/20/17.山东红富士苹果_20250820173807A017.png', '山东烟台', '山东烟台', 1000.00, '5斤装', '常温20天，冷藏45天', '阴凉干燥处存放', '即食', '<h2><strong>产品详情</strong></h2><p>山东烟台红富士苹果，果形端正，色泽鲜艳，肉质细脆，酸甜适口。</p><p><br></p><h2><strong>种植环境</strong></h2><p>烟台丘陵地带，昼夜温差大，有利于糖分积累。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工精选，坏果包赔。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('d56ecc4215e64349a5362256ab6b9dee', '陕西猕猴桃', '果肉翠绿，酸甜适中，富含维生素C', 19.90, '/profile/upload/2025/08/20/18.陕西猕猴桃_20250820173812A018.png', '陕西周至', '陕西周至', 1000.00, '12个装', '催熟后冷藏7天', '常温催熟后冷藏', '需催熟', '<h2><strong>产品详情</strong></h2><p>陕西周至猕猴桃，果肉翠绿，酸甜适中，富含维生素C。</p><p><br></p><h2><strong>种植环境</strong></h2><p>秦岭北麓独特气候，昼夜温差大，糖分积累充足。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工精选，坏果包赔。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('d5e73ddb0571409f95e0db884d7a74c0', '新疆若羌灰枣', '若羌灰枣，自然吊干，皮薄肉厚，甜度高达70%以上', 32.90, '/profile/upload/2025/08/20/19.新疆若羌灰枣_20250820173816A019.png', '新疆若羌', '新疆巴州', 996.00, '500g袋装', '密封12个月', '阴凉干燥', '即食', '<h2><strong>产品详情</strong></h2><p>若羌灰枣，自然吊干，皮薄肉厚，甜度高达70%以上。</p><p><br></p><h2><strong>种植环境</strong></h2><p>塔克拉玛干沙漠边缘，全年超3000小时日照。</p><p><br></p><h2><strong>品质保证</strong></h2><p>免洗即食，无添加。</p>', 103, '2025-08-12 23:34:32');
INSERT INTO `products` VALUES ('fdba5b1ba2ce4f8c98b8a80f079a794d', '林芝野生松茸', '海拔3500米野生松茸，菌肉肥厚，香气浓郁', 398.00, '/profile/upload/2025/08/20/20.林芝野生松茸_20250820173820A020.png', '西藏林芝', '西藏林芝', 996.00, '100g（5-7cm）', '冷冻6个月', '-18℃冷冻', '需烹饪', '<h2><strong>产品详情</strong></h2><p>海拔3500米野生松茸，菌肉肥厚，香气浓郁。</p><p><br></p><h2><strong>生长环境</strong></h2><p>雅鲁藏布江流域原始森林，无污染环境。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工采摘后12小时内急冻。</p>', 103, '2025-08-12 23:34:32');
