INSERT INTO `sys_oper_log` VALUES (322, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高。</p><p><br></p><h2><strong>种植环境</strong></h2><p>哀牢山梯田种植，精准水肥管理。</p><p><br></p><h2><strong>品质保证</strong></h2><p>糖度检测，单果≥13度。</p>\",\"edible\":\"即食\",\"expire\":\"常温10天，冷藏20天\",\"image\":\"/profile/upload/2025/08/20/云南冰糖橙_20250820110424A001.png\",\"inventory\":300,\"name\":\"云南冰糖橙\",\"origin\":\"云南新平\",\"params\":{},\"price\":39.9,\"productsId\":\"0c212c1dea134749ac07fc20ae097fb6\",\"shipFrom\":\"云南玉溪\",\"specs\":\"5斤家庭装\",\"storage\":\"阴凉干燥\",\"subtitle\":\"冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 11:04:25', 19);
INSERT INTO `sys_oper_log` VALUES (323, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>新疆库尔勒香梨，皮薄肉细，汁多味甜，酥脆爽口，被誉为\'梨中珍品\'。</p><p><br></p><h2><strong>种植环境</strong></h2><p>生长在塔里木盆地北缘，充足的日照和天山雪水灌溉造就了独特风味。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工精选，大小均匀，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"常温10天，冷藏20天\",\"image\":\"/profile/upload/2025/08/20/2.新疆库尔勒香梨_20250820110449A002.png\",\"inventory\":0,\"name\":\"新疆库尔勒香梨\",\"origin\":\"新疆库尔勒\",\"params\":{},\"price\":15.9,\"productsId\":\"120d6b68e06f43958801a5656736dcf7\",\"shipFrom\":\"新疆库尔勒\",\"specs\":\"3斤装\",\"storage\":\"阴凉通风处存放\",\"subtitle\":\"皮薄肉细，汁多味甜，酥脆爽口\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 11:04:51', 6);
INSERT INTO `sys_oper_log` VALUES (324, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>我们的高原有机苹果生长在甘肃张掖海拔1500米以上的高原地区，昼夜温差大，光照充足，使得苹果糖分积累充足，口感脆甜。</p><p><br></p><h2><strong>种植环境</strong></h2><p>果园位于祁连山脚下，空气清新，水源纯净，采用有机种植方式，不使用化学农药和化肥，完全依靠有机肥料和生物防治。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每一颗苹果都经过严格筛选，确保大小均匀，色泽鲜艳，无瑕疵。我们承诺如收到坏果，将按比例赔偿。</p>\",\"edible\":\"即食\",\"expire\":\"常温15天，冷藏30天\",\"image\":\"/profile/upload/2025/08/20/3.高原有机苹果_20250820110505A003.png\",\"inventory\":0,\"name\":\"高原有机苹果\",\"origin\":\"甘肃张掖\",\"params\":{},\"price\":12.8,\"productsId\":\"20c59e8a5614416eb07917f7201dcd73\",\"shipFrom\":\"甘肃张掖\",\"specs\":\"5斤装\",\"storage\":\"阴凉干燥处存放或冷藏\",\"subtitle\":\"甘肃张掖高海拔种植，自然成熟，香甜脆爽\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 11:05:06', 6);
INSERT INTO `sys_oper_log` VALUES (325, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺。</p><p><br></p><h2><strong>种植环境</strong></h2><p>五龙河冲积沙土种植，富含矿物质。</p><p><br></p><h2><strong>品质保证</strong></h2><p>现摘现发，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"常温7天，冷藏15天\",\"image\":\"/profile/upload/2025/08/20/4.莱阳沙地梨_20250820110515A004.png\",\"inventory\":0,\"name\":\"莱阳沙地梨\",\"origin\":\"山东莱阳\",\"params\":{},\"price\":28.8,\"productsId\":\"2aa126b04ddc403da657f64061c7a8a1\",\"shipFrom\":\"山东烟台\",\"specs\":\"5斤精品装\",\"storage\":\"阴凉通风\",\"subtitle\":\"莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 11:05:16', 6);
INSERT INTO `sys_oper_log` VALUES (326, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美。</p><p><br></p><h2><strong>种植环境</strong></h2><p>四川盆地丘陵地带，全年超2000小时日照。</p><p><br></p><h2><strong>品质保证</strong></h2><p>单果套袋，坏果按个赔付。</p>\",\"edible\":\"即食\",\"expire\":\"常温7天，冷藏15天\",\"image\":\"/profile/upload/2025/08/20/5.四川爱媛38号橙_20250820110525A005.png\",\"inventory\":0,\"name\":\"四川爱媛38号橙\",\"origin\":\"四川丹棱\",\"params\":{},\"price\":22.5,\"productsId\":\"2c1af27393734311b1d7f84fda73f7a9\",\"shipFrom\":\"四川眉山\",\"specs\":\"5斤精品装\",\"storage\":\"阴凉通风\",\"subtitle\":\"果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 11:05:25', 4);
