INSERT INTO `sys_oper_log` VALUES (374, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高。</p><p><br></p><h2><strong>种植环境</strong></h2><p>哀牢山梯田种植，精准水肥管理。</p><p><br></p><h2><strong>品质保证</strong></h2><p>糖度检测，单果≥13度。</p>\",\"edible\":\"即食\",\"expire\":\"常温10天，冷藏20天\",\"image\":\"/profile/upload/2025/08/20/1.云南冰糖橙_20250820173435A001.png\",\"inventory\":300,\"name\":\"云南冰糖橙\",\"origin\":\"云南新平\",\"params\":{},\"price\":39.9,\"productsId\":\"0c212c1dea134749ac07fc20ae097fb6\",\"shipFrom\":\"云南玉溪\",\"specs\":\"5斤家庭装\",\"storage\":\"阴凉干燥\",\"subtitle\":\"冰糖橙品种，果肉脆嫩，甜酸比24:1，化渣率高\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:34:36', 16);
INSERT INTO `sys_oper_log` VALUES (375, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>新疆库尔勒香梨，皮薄肉细，汁多味甜，酥脆爽口，被誉为\'梨中珍品\'。</p><p><br></p><h2><strong>种植环境</strong></h2><p>生长在塔里木盆地北缘，充足的日照和天山雪水灌溉造就了独特风味。</p><p><br></p><h2><strong>品质保证</strong></h2><p>人工精选，大小均匀，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"常温10天，冷藏20天\",\"image\":\"/profile/upload/2025/08/20/2.新疆库尔勒香梨_20250820173440A002.png\",\"inventory\":0,\"name\":\"新疆库尔勒香梨\",\"origin\":\"新疆库尔勒\",\"params\":{},\"price\":15.9,\"productsId\":\"120d6b68e06f43958801a5656736dcf7\",\"shipFrom\":\"新疆库尔勒\",\"specs\":\"3斤装\",\"storage\":\"阴凉通风处存放\",\"subtitle\":\"皮薄肉细，汁多味甜，酥脆爽口\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:34:41', 4);
INSERT INTO `sys_oper_log` VALUES (376, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>我们的高原有机苹果生长在甘肃张掖海拔1500米以上的高原地区，昼夜温差大，光照充足，使得苹果糖分积累充足，口感脆甜。</p><p><br></p><h2><strong>种植环境</strong></h2><p>果园位于祁连山脚下，空气清新，水源纯净，采用有机种植方式，不使用化学农药和化肥，完全依靠有机肥料和生物防治。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每一颗苹果都经过严格筛选，确保大小均匀，色泽鲜艳，无瑕疵。我们承诺如收到坏果，将按比例赔偿。</p>\",\"edible\":\"即食\",\"expire\":\"常温15天，冷藏30天\",\"image\":\"/profile/upload/2025/08/20/3.高原有机苹果_20250820173445A003.png\",\"inventory\":0,\"name\":\"高原有机苹果\",\"origin\":\"甘肃张掖\",\"params\":{},\"price\":12.8,\"productsId\":\"20c59e8a5614416eb07917f7201dcd73\",\"shipFrom\":\"甘肃张掖\",\"specs\":\"5斤装\",\"storage\":\"阴凉干燥处存放或冷藏\",\"subtitle\":\"甘肃张掖高海拔种植，自然成熟，香甜脆爽\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:34:45', 5);
INSERT INTO `sys_oper_log` VALUES (377, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺。</p><p><br></p><h2><strong>种植环境</strong></h2><p>五龙河冲积沙土种植，富含矿物质。</p><p><br></p><h2><strong>品质保证</strong></h2><p>现摘现发，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"常温7天，冷藏15天\",\"image\":\"/profile/upload/2025/08/20/4.莱阳沙地梨_20250820173450A004.png\",\"inventory\":0,\"name\":\"莱阳沙地梨\",\"origin\":\"山东莱阳\",\"params\":{},\"price\":28.8,\"productsId\":\"2aa126b04ddc403da657f64061c7a8a1\",\"shipFrom\":\"山东烟台\",\"specs\":\"5斤精品装\",\"storage\":\"阴凉通风\",\"subtitle\":\"莱阳茌梨，肉质细嫩，汁多无渣，止咳润肺\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:34:51', 4);
INSERT INTO `sys_oper_log` VALUES (378, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美。</p><p><br></p><h2><strong>种植环境</strong></h2><p>四川盆地丘陵地带，全年超2000小时日照。</p><p><br></p><h2><strong>品质保证</strong></h2><p>单果套袋，坏果按个赔付。</p>\",\"edible\":\"即食\",\"expire\":\"常温7天，冷藏15天\",\"image\":\"/profile/upload/2025/08/20/5.四川爱媛38号橙_20250820173456A005.png\",\"inventory\":0,\"name\":\"四川爱媛38号橙\",\"origin\":\"四川丹棱\",\"params\":{},\"price\":22.5,\"productsId\":\"2c1af27393734311b1d7f84fda73f7a9\",\"shipFrom\":\"四川眉山\",\"specs\":\"5斤精品装\",\"storage\":\"阴凉通风\",\"subtitle\":\"果冻橙品种，皮薄易剥，果肉细嫩无渣，酸甜比完美\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:34:56', 5);
INSERT INTO `sys_oper_log` VALUES (379, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>正宗阳澄湖产区，蟹黄饱满，蟹肉鲜甜，青背白肚金爪。</p><p><br></p><h2><strong>养殖环境</strong></h2><p>湖心水域围网养殖，投喂小鱼螺蛳。</p><p><br></p><h2><strong>品质保证</strong></h2><p>佩戴防伪戒指，死蟹包赔。</p>\",\"edible\":\"需蒸煮\",\"expire\":\"鲜活运输，收货后冷藏3天\",\"image\":\"/profile/upload/2025/08/20/6.阳澄湖大闸蟹_20250820173501A006.png\",\"inventory\":0,\"name\":\"阳澄湖大闸蟹\",\"origin\":\"江苏苏州\",\"params\":{},\"price\":198,\"productsId\":\"2c1e980af1f14700ae63e2661e246f03\",\"shipFrom\":\"江苏昆山\",\"specs\":\"4只装（3两/只）\",\"storage\":\"冷藏保湿\",\"subtitle\":\"正宗阳澄湖产区，蟹黄饱满，蟹肉鲜甜，青背白肚金爪\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:35:01', 4);
INSERT INTO `sys_oper_log` VALUES (380, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>妃子笑荔枝，果大核小，肉厚多汁，酸甜比例恰到好处。</p><p><br></p><h2><strong>种植环境</strong></h2><p>茂名高州核心产区，火山岩土壤种植，日照充足。</p><p><br></p><h2><strong>品质保证</strong></h2><p>清晨采摘，冷链运输，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"冷藏3-5天\",\"image\":\"/profile/upload/2025/08/20/8.茂名妃子笑荔枝_20250820173508A007.png\",\"inventory\":0,\"name\":\"茂名妃子笑荔枝\",\"origin\":\"广东茂名\",\"params\":{},\"price\":36.8,\"productsId\":\"3ac3b3ac46d84eff81c80244f259ede9\",\"shipFrom\":\"广东茂名\",\"specs\":\"3斤礼盒装\",\"storage\":\"冷藏保存\",\"subtitle\":\"妃子笑荔枝，果大核小，肉厚多汁，酸甜比例恰到好处\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:35:09', 4);
INSERT INTO `sys_oper_log` VALUES (381, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>五常核心产区稻花香大米，米粒细长，油润饱满，蒸煮后饭香浓郁。</p><p><br></p><h2><strong>种植环境</strong></h2><p>黑土地种植，松花江水源灌溉，一年一季慢生长。</p><p><br></p><h2><strong>品质保证</strong></h2><p>当季新米，真空包装，假一赔十。</p>\",\"edible\":\"需烹饪\",\"expire\":\"阴凉干燥处12个月\",\"image\":\"/profile/upload/2025/08/20/7.五常稻花香大米_20250820173512A008.png\",\"inventory\":0,\"name\":\"五常稻花香大米\",\"origin\":\"黑龙江五常\",\"params\":{},\"price\":89.9,\"productsId\":\"37bdaacbd96446a1baef0d424d1c16da\",\"shipFrom\":\"黑龙江哈尔滨\",\"specs\":\"5kg装\",\"storage\":\"避光防潮\",\"subtitle\":\"五常核心产区稻花香大米，米粒细长，油润饱满，饭香浓郁\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:35:13', 5);
