INSERT INTO `sys_oper_log` VALUES (383, '农户产品', 2, 'com.huacai.assisting.controller.ProductsController.edit()', 'PUT', 1, 'admin', '花菜编程', '/assisting/products', '127.0.0.1', '内网IP', '{\"createTime\":\"2025-08-12 23:34:32\",\"detail\":\"<h2><strong>产品详情</strong></h2><p>福建琯溪蜜柚，果大皮薄，瓤肉无籽，汁多柔软，清甜微酸。</p><p><br></p><h2><strong>种植环境</strong></h2><p>福建平和县独特气候条件，采用有机种植。</p><p><br></p><h2><strong>品质保证</strong></h2><p>每个蜜柚独立包装，坏果包赔。</p>\",\"edible\":\"即食\",\"expire\":\"常温30天\",\"image\":\"/profile/upload/2025/08/20/10.福建琯溪蜜柚_20250820173732A010.png\",\"inventory\":0,\"name\":\"福建琯溪蜜柚\",\"origin\":\"福建平和\",\"params\":{},\"price\":39.9,\"productsId\":\"46d60aecaf2b4d5a95449257f31a5a17\",\"shipFrom\":\"福建平和\",\"specs\":\"1个装(约2.5kg)\",\"storage\":\"阴凉通风处存放\",\"subtitle\":\"果大皮薄，瓤肉无籽，汁多柔软，清甜微酸\",\"userId\":100}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-08-20 17:37:33', 4);
